package kr.remerge.stylehub.domain.order.service;

import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class OrderService {
    private final OrderRepository orderRepository;
    private final StockRepository stockRepository;
    private final NotificationClient notificationClient;

    // 주문 후 알림을 보낸다. 알림 실패가 주문을 롤백시키지 않도록 저장 부분만 트랜잭션으로 분리
    public Long placeOrder(Long buyerId, Long optionId, int quantity) {
        Long orderId = this.saveOrder(buyerId, optionId, quantity);
        notificationClient.sendOrderPlaced(buyerId, orderId);
        return orderId;
    }

    @Transactional
    public Long saveOrder(Long buyerId, Long optionId, int quantity) {
        stockRepository.decrease(optionId, quantity);
        return orderRepository.save(Order.create(buyerId, optionId, quantity)).getId();
    }
}
